const e = $json.body ?? $json;

// watchdog.py solo hace POST cuando hay algo que contar, asi que
// no hace falta un IF: si llego aqui, hay hallazgo.
// Las rutas las elige quien deja el archivo: sin escapar, un nombre con '<' o '&'
// hace que Telegram rechace el mensaje HTML y la alerta se pierde.
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lista = (arr) => (arr && arr.length)
  ? arr.map(x => '\u2022 <code>' + esc(x.ruta) + '</code> (' + esc(x.bytes) + ' B)').join('\n')
  : '\u2014';

const nuevos = e.nuevos || [];
const modificados = e.modificados || [];

// Un PHP nuevo dentro de uploads es el patron clasico de webshell:
// merece mas urgencia que un zip suelto.
const webshell = nuevos.some(x => /^wp-content\/uploads\/.*\.(php|phtml|php5|phar)$/i.test(x.ruta));

const mensaje = [
  webshell ? '\uD83D\uDEA8 <b>WATCHDOG - posible webshell en uploads</b>'
           : '\u26A0\uFE0F <b>WATCHDOG - cambios en el web root</b>',
  '',
  '<b>Host:</b> ' + esc(e.host || 'n/d'),
  '',
  '<b>Nuevos:</b>',
  lista(nuevos),
  '',
  '<b>Modificados:</b>',
  lista(modificados),
  '',
  '<b>Archivos vigilados:</b> ' + esc(e.vigilados ?? 'n/d'),
  '',
  'Si no reconoces estos archivos, revisa ahora: un respaldo o un PHP nuevo en el web root es exactamente como empieza una exposicion de respaldos.'
].join('\n');

return [{ json: { ...e, webshell, mensaje } }];
